mapper.select:
select l.SLIP_LN_ID, l.SLIP_ID, l.WRITE_OFF_TYPE, l.WRITE_OFF_DATE, l.WRITE_OFF_DUE_AMOUNT, l.WRITE_OFF_INTEREST, l.WRITE_OFF_PRINCIPAL, l.CSH_TRANSACTION_ID, l.BP_ID, l.CONTRACT_ID, l.CONTRACT_NUMBER, l.CASHFLOW_ID, l.CF_ITEM, l.CF_TYPE, l.CF_STATUS, l.CF_DIRECTION, l.TIMES, l.DUE_DATE, l.DUE_AMOUNT, l.SURPLUS_AMOUNT_FLAG, l.ARRIVE_MODALITY, l.CSH_WRITE_OFF_AMOUNT, l.REVERSED_DATE, l.REVERSED_FLAG, l.SUBSEQ_CSH_WRITE_OFF_AMOUNT, l.SUBSEQUENT_CSH_TRX_ID, l.TRANSACTION_DATE, l.TRANSACTION_TYPE, l.WRITE_OFF_DOC_CATEGORY, l.WRITE_OFF_ID, l.DESCRIPTION, l.ADVANCE_BP_ID, l.SURPLUS_AMOUNT, l.INSERT_FLAG, (select ccc.DUE_AMOUNT - nvl(ccc.BLOCK_AMOUNT,0) - nvl(ccc.RECEIVED_AMOUNT, 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CASHFLOW_ID = l.CASHFLOW_ID) as CASHFLOW_SURPLUS_AMOUNT, (select ccc.PRINCIPAL - nvl(ccc.BLOCK_PRINCIPAL,0) - nvl(ccc.RECEIVED_PRINCIPAL, 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CASHFLOW_ID = l.CASHFLOW_ID) as CASHFLOW_SURPLUS_PRINCIPAL, (select ccc.INTEREST - nvl(ccc.BLOCK_INTEREST,0) - nvl(ccc.RECEIVED_INTEREST, 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CASHFLOW_ID = l.CASHFLOW_ID) as CASHFLOW_SURPLUS_INTEREST, (select ccc.PRINCIPAL - nvl(ccc.BLOCK_PRINCIPAL,0) - nvl(ccc.RECEIVED_PRINCIPAL, 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CASHFLOW_ID = l.CASHFLOW_ID) as surplus_principal, (select ccc.INTEREST - nvl(ccc.BLOCK_INTEREST,0) - nvl(ccc.RECEIVED_INTEREST, 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CASHFLOW_ID = l.CASHFLOW_ID) as surplus_interest, to_char(l.DUE_DATE, 'yyyy-MM-dd') as due_date_format, (select m.bp_name from hls_bp_master m where m.bp_id = l.advance_bp_id) as advance_bp_name, (select m.bp_name from hls_bp_master m where m.bp_id = cc.BP_ID_TENANT) as bp_name, (select m.bp_name from hls_bp_master m where m.bp_id = cc.BP_ID_TENANT) as tenant_name, (select hci.DESCRIPTION from HLS_CASHFLOW_ITEM hci where hci.CF_ITEM = l.CF_ITEM) as CF_ITEM_N, (select scvb.MEANING from SYS_CODE_B scb , SYS_CODE_VALUE_B scvb where scb.CODE = 'CSH301_WRITE_OFF_TYPE' and scb.CODE_ID = scvb.CODE_ID and scvb.VALUE = l.WRITE_OFF_TYPE) as WRITE_OFF_TYPE_N, (select scvb.MEANING from SYS_CODE_B scb , SYS_CODE_VALUE_B scvb where scb.CODE = 'CSH301_WRITE_OFF_TYPE' and scb.CODE_ID = scvb.CODE_ID and scvb.VALUE = l.WRITE_OFF_TYPE) as WRITE_OFF_TYPE_DESC, (select scvb.MEANING from SYS_CODE_B scb , SYS_CODE_VALUE_B scvb where scb.CODE = 'CSH001_ARRIVE_MODALITY' and scb.CODE_ID = scvb.CODE_ID and scvb.VALUE = l.ARRIVE_MODALITY) as arrive_modality_desc, (select scvb.MEANING from SYS_CODE_B scb, SYS_CODE_VALUE_B scvb where scb.CODE = 'CSH301_TRANSACTION_TYPE' and scb.CODE_ID = scvb.CODE_ID and scvb.VALUE = l.TRANSACTION_TYPE) as transaction_type_n from CSH_WRITE_OFF_SLIP_LN l left join CON_CONTRACT cc on l.CONTRACT_ID = cc.CONTRACT_ID
and l.slip_id = #{slipId}
and l.write_off_type in
#{item}
and l.slip_id in
#{item,jdbcType=DECIMAL}
